plugins {
    // Apply the application plugin to add support for building a CLI application in Java.
    application
    alias(libs.plugins.javafx.plugin)
}

repositories {
    // Use Maven Central for resolving dependencies.
    mavenCentral()
}

// Generated by https://www.lwjgl.org/customize
val lwjglNatives = Pair(
	System.getProperty("os.name")!!,
	System.getProperty("os.arch")!!
).let { (name, arch) ->
	when {
		"FreeBSD".equals(name)                                    ->
			"natives-freebsd"
		arrayOf("Linux", "SunOS", "Unit").any { name.startsWith(it) } ->
			if (arrayOf("arm", "aarch64").any { arch.startsWith(it) })
				"natives-linux${if (arch.contains("64") || arch.startsWith("armv8")) "-arm64" else "-arm32"}"
			else if (arch.startsWith("ppc"))
				"natives-linux-ppc64le"
			else if (arch.startsWith("riscv"))
				"natives-linux-riscv64"
			else
				"natives-linux"
		arrayOf("Mac OS X", "Darwin").any { name.startsWith(it) }     ->
			"natives-macos${if (arch.startsWith("aarch64")) "-arm64" else ""}"
		arrayOf("Windows").any { name.startsWith(it) }                ->
			if (arch.contains("64"))
				"natives-windows${if (arch.startsWith("aarch64")) "-arm64" else ""}"
			else
				"natives-windows-x86"
		else                                                                            ->
			throw Error("Unrecognized or unsupported platform. Please set \"lwjglNatives\" manually")
	}
}

dependencies {
    // This dependency is used by the application.
    implementation(libs.guava)

    implementation(platform(libs.lwjgl.bom))
    implementation(libs.lwjgl.lib)
    implementation(libs.lwjgl.opengl)
    runtimeOnly(variantOf(libs.lwjgl.lib) { classifier(lwjglNatives) })
    runtimeOnly(variantOf(libs.lwjgl.opengl) { classifier(lwjglNatives) })
}

testing {
    suites {
        // Configure the built-in test suite
        val test by getting(JvmTestSuite::class) {
            // Use JUnit Jupiter test framework
            useJUnitJupiter("5.10.3")
        }
    }
}

// Apply a specific Java toolchain to ease working on different environments.
java {
    toolchain {
        languageVersion = JavaLanguageVersion.of(21)
    }
}

javafx {
    version = libs.versions.javafx.lib.get()
    modules("javafx.controls")
}

application {
    // Define the main class for the application.
    mainClass = "com.blackbox.app.App"
}
